 "content": "from collections import deque


def components(grid):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == _background(grid) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return result


def _background(grid):
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    objs = components(grid)
    border = [(color, cells) for color, cells in objs
              if any(r == 0 or r == h-1 or c == 0 or c == w-1 for r, c in cells)]
    # A border-reaching line/L is the color key; recolor the repeated matching
    # motif closest to that key.
    keys = [(color, cells) for color, cells in border
            if len(cells) >= 3 and (len({r for r, c in cells}) == 1 or len({c for r, c in cells}) == 1
                                   or (len({r for r, c in cells}) > 1 and len({c for r, c in cells}) > 1))]
    if not keys:
        return out
    key_color, key_cells = max(keys, key=lambda item: len(item[1]))
    matches = []
    for i, (color, cells) in enumerate(objs):
        for j, (other_color, other) in enumerate(objs):
            if i != j and color != other_color and _shape(cells) == _shape(other):
                distance = min(abs(r-y) + abs(c-x) for r, c in cells for y, x in key_cells)
                matches.append((distance, cells))
                break
    if matches:
        _, chosen = min(matches, key=lambda item: item[0])
        for r, c in chosen:
            out[r][c] = key_color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
